--
-- One permissive policy per setting that may admit a row; the application
-- role sees and writes nothing a placed setting does not name. The owner that
-- runs this file is not bound by them (no `FORCE ROW LEVEL SECURITY`), so the
-- migrations and the harness's truncate are unaffected.
--
-- **Blocking, briefly** (ADR-0060 §5). `ENABLE ROW LEVEL SECURITY` and each
-- `CREATE POLICY` take an `ACCESS EXCLUSIVE` lock on their table, but they are
-- catalogue changes that read no rows, so each holds it for as long as the
-- statement's own bookkeeping — a membership read or an invitation write
-- waits that long and no longer, whatever the table's size.
ALTER TABLE "organization_invitations" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "organization_memberships" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "organization_invitations_tenant" ON "organization_invitations" AS PERMISSIVE FOR ALL TO public USING (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "organization_invitations_invitee" ON "organization_invitations" AS PERMISSIVE FOR SELECT TO public USING (email = (select u.email from users u where u.id = nullif(current_setting('app.user_id', true), '')::uuid and u.deleted_at is null));--> statement-breakpoint
CREATE POLICY "organization_invitations_invitee_consume" ON "organization_invitations" AS PERMISSIVE FOR UPDATE TO public USING (email = (select u.email from users u where u.id = nullif(current_setting('app.user_id', true), '')::uuid and u.deleted_at is null));--> statement-breakpoint
CREATE POLICY "organization_invitations_bearer" ON "organization_invitations" AS PERMISSIVE FOR SELECT TO public USING (token_hash = nullif(current_setting('app.invitation_token_hash', true), ''));--> statement-breakpoint
CREATE POLICY "organization_invitations_bearer_consume" ON "organization_invitations" AS PERMISSIVE FOR UPDATE TO public USING (token_hash = nullif(current_setting('app.invitation_token_hash', true), ''));--> statement-breakpoint
CREATE POLICY "organization_invitations_unscoped" ON "organization_invitations" AS PERMISSIVE FOR ALL TO public USING (nullif(current_setting('app.tenant_unscoped', true), '') in ('staff', 'system'));--> statement-breakpoint
CREATE POLICY "organization_memberships_tenant" ON "organization_memberships" AS PERMISSIVE FOR ALL TO public USING (organization_id = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
